if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#ff5e62", "#ff9966", "#ffe066", "#2c3e50", "#3498db"];
var speedMult = 1.0;
var lineScale = 1.0;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'FibonacciCurl' by 'Ivan Rudnicki' ===
// Created as variant #2 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
// For #genuary2026, day 03: "fibonacci forever".

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(10, 10, 15);
	types = [OPEN, CHORD, PIE];
	dim = -PI;
	tindex = 2;
	sequence = generateFibonacci(15);
	lastdim = dim;
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

	dim = 2 * TAU * sin(frameCount / 300);
	lastdim = dim;
	rotateZ(dim / 2)
	rotateY(dim / 2);
	rotateX(dim / 2);
	drawCurl();

  pop();
}

function drawCurl() {
	for (let i = 0; i < sequence.length; i++) {
		let r = sequence[i] * dim;
		noFill();
		stroke(255, 50);
		strokeWeight(0.2);
		if (i > 2) translate(-(sequence[i - 1] * abs(dim)) / 2 + (sequence[i - 3] * abs(dim)) / 2, 0);
		arc(0, 0, r, r, 0, HALF_PI, types[tindex]);
		rotate(HALF_PI);
	}
}

function mousePressed() {
	fullscreen(true);
	tindex = (tindex + 1) % types.length;
	background(10, 10, 15);
}

function generateFibonacci(n) {
	let fib = [0, 1];
	for (let i = 2; i < n; i++) {
		fib.push(fib[i - 1] + fib[i - 2]);
	}
	return fib;
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
